import {BOSS_DEFINITIONS} from './boss-definitions.mjs';
export const STATES=['idle','appear','challenge','progress','encourage','timeout','celebrate','ascend'];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const CSS=`.boss-rig{transform-origin:160px 180px;animation:boss-breathe var(--speed) ease-in-out infinite}.boss-left,.boss-right{transform-box:fill-box;transform-origin:50% 10%}.boss-tail{transform-origin:210px 210px;animation:boss-tail 3s ease-in-out infinite}.boss-wing{transform-origin:160px 150px;animation:boss-wing 2s ease-in-out infinite}.boss-eyes{animation:boss-blink 5s infinite;transform-origin:160px 130px}.boss-aura{transform-origin:160px 160px;animation:boss-orbit 20s linear infinite}.boss-particles{animation:boss-glow 2s ease-in-out infinite}.b-appear .boss-rig{animation:boss-arrive .8s both}.b-challenge .boss-right{animation:boss-wave calc(var(--speed)*.6) infinite}.b-progress .boss-left{animation:boss-wave calc(var(--speed)*.8) infinite}.b-encourage .boss-right,.b-celebrate .boss-right{animation:boss-wave calc(var(--speed)*.3) infinite}.b-timeout .boss-rig{animation:boss-sigh 4s infinite}.b-timeout .boss-aura{opacity:.15}.b-celebrate .boss-rig{animation:boss-hop calc(var(--speed)*.4) infinite}.b-ascend .boss-rig{animation:boss-rise calc(var(--speed)*1.2) infinite}.b-ascend .boss-aura{animation:boss-orbit 5s linear infinite}.boss-caption{font:13px system-ui;fill:#29473d;text-anchor:middle}@keyframes boss-breathe{50%{transform:translateY(-5px) scale(1.015)}}@keyframes boss-tail{50%{transform:rotate(12deg)}}@keyframes boss-wing{50%{transform:scaleX(.9) rotate(-4deg)}}@keyframes boss-blink{0%,42%,46%,100%{transform:scaleY(1)}44%{transform:scaleY(.08)}}@keyframes boss-orbit{to{transform:rotate(360deg)}}@keyframes boss-glow{50%{opacity:.25}}@keyframes boss-arrive{from{opacity:0;transform:translateY(25px) scale(.7)}to{opacity:1;transform:none}}@keyframes boss-wave{50%{transform:rotate(var(--wave-angle))}}@keyframes boss-sigh{50%{transform:translateY(4px) rotate(-3deg)}}@keyframes boss-hop{50%{transform:translateY(var(--hop))}}@keyframes boss-rise{50%{transform:translateY(-15px)}}@media(prefers-reduced-motion:reduce){.g-boss *{animation:none!important}}.g-boss.b-still *{animation:none!important}`;
function face(d){const ears=d.ears==='long'?'<ellipse cx="120" cy="64" rx="14" ry="40"/><ellipse cx="200" cy="64" rx="14" ry="40"/>':d.ears==='point'?'<path d="M99 100 102 47 140 83ZM181 83 219 47 221 105Z"/>':d.ears==='round'?'<circle cx="105" cy="85" r="21"/><circle cx="215" cy="85" r="21"/>':'';const head=d.family==='bird'?'<ellipse cx="160" cy="123" rx="62" ry="53"/><path d="m148 137 12 16 12-16Z" fill="'+d.gold+'"/>':d.family==='dragon'?'<path d="M105 112Q92 78 137 77L160 68 182 77Q228 78 215 117Q232 154 194 169H124Q88 153 105 112Z"/><path d="m115 81-12-36 31 30m52 0 31-30-12 36" stroke="'+d.gold+'" stroke-width="9" fill="none"/>':d.family==='spirit'?'<path d="M97 124Q97 66 160 68Q224 66 223 124L230 162 205 153 184 168 160 155 135 168 112 153 90 162Z"/>':'<ellipse cx="160" cy="123" rx="63" ry="54"/>';return `<g fill="${d.skin}" stroke="${d.line}" stroke-width="3" stroke-linejoin="round">${ears}${head}</g><g class="boss-eyes" fill="${d.line}"><ellipse cx="137" cy="126" rx="7" ry="10"/><ellipse cx="183" cy="126" rx="7" ry="10"/><circle cx="139" cy="122" r="2" fill="white"/><circle cx="185" cy="122" r="2" fill="white"/></g><ellipse cx="120" cy="143" rx="10" ry="5" fill="#edb6ab" opacity=".6"/><ellipse cx="200" cy="143" rx="10" ry="5" fill="#edb6ab" opacity=".6"/><path d="M150 148q10 9 20 0" stroke="${d.line}" stroke-width="3" fill="none"/>`;}
function prop(d){const c=d.gold;switch(d.prop){case 'sword':return `<path d="m235 175 7-63 7 63-7 18Z" fill="#e1eee8" stroke="${d.line}" stroke-width="3"/><path d="M229 179h26m-13 0v23" stroke="${c}" stroke-width="7"/>`;case 'lantern':return `<path d="M234 154v-39h25" fill="none" stroke="${c}" stroke-width="4"/><rect x="238" y="119" width="32" height="38" rx="12" fill="${d.accent}" stroke="${c}" stroke-width="3"/><path d="M254 157v19" stroke="${c}" stroke-width="3"/>`;case 'staff':return `<path d="M244 91v119" stroke="${c}" stroke-width="7"/><circle cx="244" cy="89" r="15" fill="${d.accent}" stroke="${c}" stroke-width="4"/>`;case 'book':return `<path d="M222 147q20-9 40 0v43q-20-9-40 0Z" fill="#faf0ce" stroke="${c}" stroke-width="4"/><path d="M230 157h22m-22 10h18" stroke="${d.line}" stroke-width="2"/>`;case 'fan':return `<path d="M240 188 210 147Q241 115 272 147Z" fill="${d.accent}" stroke="${c}" stroke-width="3"/><path d="m240 188-16-45m16 45 17-45m-17 45v-51" stroke="${c}" stroke-width="2"/>`;case 'shield':return `<path d="M224 141h39v37q-18 30-39 0Z" fill="${d.accent}" stroke="${c}" stroke-width="4"/>`;default:return `<circle cx="243" cy="161" r="21" fill="${d.accent}" stroke="${c}" stroke-width="4"/><path d="M230 161h26m-13-13v26" stroke="${c}" stroke-width="3"/>`;}}
function extras(d){let e='';if(d.wings)e+=`<g class="boss-wing" fill="${d.accent}" stroke="${d.line}" stroke-width="3"><path d="M111 173Q42 92 42 158Q43 200 115 209ZM209 173Q278 92 278 158Q277 200 205 209Z"/></g>`;if(d.tail)e+=`<path class="boss-tail" d="M210 215Q289 223 255 170Q246 157 245 183Q247 205 211 198" fill="${d.skin}" stroke="${d.line}" stroke-width="4"/>`;if(d.family==='tree')e+=`<g fill="${d.accent}" stroke="${d.line}" stroke-width="2"><circle cx="111" cy="74" r="28"/><circle cx="155" cy="52" r="32"/><circle cx="199" cy="74" r="28"/></g>`;if(d.family==='insect')e+=`<g stroke="${d.line}" stroke-width="5" fill="none"><path d="M108 185 74 166 60 181m49 20-40 4-13 16m153-36 34-19 14 15m-49 20 40 4 13 16M140 81l-11-33m51 33 11-33"/></g>`;return e;}
export function renderBoss(id,state='idle',motion=true){const d=BOSS_DEFINITIONS[id-1];if(!d||!STATES.includes(state))throw Error('Boss hoặc trạng thái không hợp lệ');const uid='boss'+id;return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 320" class="g-boss b-${state}${motion?'':' b-still'}" role="img" aria-labelledby="${uid}-title" style="--speed:${d.speed}s;--wave-angle:-${16+id%25}deg;--hop:-${6+id%13}px"><title id="${uid}-title">${escape(d.name)} · ${state}</title><style>${CSS}</style><ellipse cx="160" cy="272" rx="87" ry="12" fill="${d.accent}" opacity=".15"/><g class="boss-aura" stroke="${d.gold}" fill="none" opacity=".45"><circle cx="160" cy="160" r="122" stroke-width="2" stroke-dasharray="${d.dash} 14"/>${Array.from({length:d.runes},(_,i)=>`<circle cx="${160+113*Math.cos(i*2*Math.PI/d.runes)}" cy="${160+113*Math.sin(i*2*Math.PI/d.runes)}" r="4" fill="${d.gold}"/>`).join('')}</g><g class="boss-rig">${extras(d)}<g fill="${d.line}"><ellipse cx="134" cy="254" rx="24" ry="10"/><ellipse cx="186" cy="254" rx="24" ry="10"/></g><path d="M112 161Q160 145 208 161L226 242Q160 272 94 242Z" fill="${d.robe}" stroke="${d.line}" stroke-width="3"/><path d="m130 164 30 67 30-67m-30 67v27" fill="none" stroke="${d.gold}" stroke-width="7"/><path d="M112 214q48 12 96 0" fill="none" stroke="${d.accent}" stroke-width="11"/><g class="boss-left"><ellipse cx="102" cy="191" rx="17" ry="29" fill="${d.robe}" stroke="${d.line}" stroke-width="3"/><circle cx="99" cy="215" r="13" fill="${d.skin}" stroke="${d.line}" stroke-width="3"/></g><g class="boss-right"><ellipse cx="218" cy="191" rx="17" ry="29" fill="${d.robe}" stroke="${d.line}" stroke-width="3"/><circle cx="220" cy="215" r="13" fill="${d.skin}" stroke="${d.line}" stroke-width="3"/>${prop(d)}</g>${face(d)}<path d="M110 96q50-${d.crownHeight} 100 0l-12-22-18 8-20-25-20 25-18-8Z" fill="${d.robe}" stroke="${d.gold}" stroke-width="3"/><circle cx="160" cy="88" r="${d.gemSize}" fill="${d.accent}" stroke="${d.gold}" stroke-width="2"/>${d.markings.map((x,i)=>`<path d="M${113+i*15} ${103+x}l7 5-5 4" stroke="${d.accent}" stroke-width="3" fill="none"/>`).join('')}<g class="boss-particles" fill="${d.gold}">${Array.from({length:d.sparks},(_,i)=>`<circle cx="${40+(i*47+id*13)%245}" cy="${45+(i*31+id*7)%205}" r="${2+i%3}"/>`).join('')}</g></g><text class="boss-caption" x="160" y="309">${escape(d.name)}</text></svg>`;}
export {BOSS_DEFINITIONS};
